const body = $input.first().json.body || {};
const title = body.title || 'Ders Notu Özeti';
const content = body.content || '';
const prompt = `Sen uzman bir eğitimci ve not özetleme asistanısın. Aşağıdaki ders notunu oku ve sadece şu JSON formatında yanıt ver:
{
  "summary": "Ders notunun akıcı ve kapsamlı 2-4 cümlelik Türkçe özeti",
  "bullet_points": ["En kritik 1. bilgi maddesi", "En kritik 2. bilgi maddesi", "En kritik 3. bilgi maddesi"],
  "key_topics": ["Konu 1", "Konu 2", "Konu 3"]
}

Ders Notu İçeriği:
${content}`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://ollama:11434/api/generate',
  body: {
    model: 'qwen2.5:3b',
    format: 'json',
    prompt: prompt,
    stream: false
  },
  json: true
});

let parsed = {};
try {
  parsed = JSON.parse(response.response);
} catch (e) {
  parsed = {
    summary: response.response,
    bullet_points: [],
    key_topics: []
  };
}

return {
  json: {
    success: true,
    title: title,
    summary: parsed.summary || 'Özet oluşturulamadı.',
    bullet_points: parsed.bullet_points || [],
    key_topics: parsed.key_topics || [],
    timestamp: new Date().toISOString()
  }
};
